import java.util.*;
public class Solution {
    public List<Integer> removeNthFromEnd(List<Integer> head, int n) {
        int idx = head.size() - n;
        List<Integer> res = new ArrayList<>(head);
        res.remove(idx);
        return res;
    }
}

