#include <vector>
using namespace std;
class Solution {
public:
    vector<int> removeNthFromEnd(vector<int>& head, int n) {
        int idx = (int)head.size() - n;
        vector<int> res = head;
        res.erase(res.begin() + idx);
        return res;
    }
};
